    prompt: `Кандидат получил наш оффер на {{POSITION}}, ЗП {{OUR_OFFER}} ₽. Его текущий работодатель предложил контроффер {{COUNTER_OFFER}} ₽ + {{COUNTER_PERKS}}.

Разыграй 3 сценария ответа в зависимости от стратегии:

СЦЕНАРИЙ А — БОРЕМСЯ (кандидат сильный, есть бюджет)
— Что ответить в мессенджер (короткий первый ответ)
— Как строить телефонный разговор
— Какие аргументы, помимо денег, использовать (задачи, команда, оборудование, стабильность отрасли, обучение)
— Red flags которые говорят "не стоит удерживать"

СЦЕНАРИЙ Б — ДЕРЖИМ ПОЗИЦИЮ (бюджет зафиксирован)
— Как вежливо отказать, не сжигая мосты
— Как узнать реальную причину (деньги ли это?)
— Формулировка для обратной связи
— Что сказать, если кандидат через 2 месяца вернётся

СЦЕНАРИЙ В — ОТПУСКАЕМ (понятно что уйдёт)
— Сообщение что уважаем его решение
— Что записать в ATS на будущее
— Просьба о рекомендации / контакте через год

КОНТЕКСТ КОМПАНИИ: {{COMPANY_CONTEXT}}
ЧТО МЫ ЗНАЕМ О КАНДИДАТЕ: {{CANDIDATE_CONTEXT}}

Пиши на русском, деловым, но человеческим тоном. Без манипуляций и давления.`,
