    description: 'Скрипт для колл-центра: скрининг-звонок за 4 минуты с автоматическим отсевом по 6 критериям.',
    prompt: `Составь скрипт 4-минутного скрининг-звонка для массового подбора {{POSITION}} на {{SITE_NAME}}.

ЦЕЛЬ: за 4 минуты понять, подходит ли кандидат, и пригласить на очное / видео собеседование.

СТРУКТУРА:

[0:00-0:30] ПРЕДСТАВЛЕНИЕ + ПОДТВЕРЖДЕНИЕ ИНТЕРЕСА
— "Здравствуйте, [Имя]. Меня зовут ..., компания ..."
— "Вы откликались на вакансию ..., она ещё интересна?"
— Если нет — вежливо прощаемся (1 вопрос про причину для аналитики)

[0:30-1:30] ОСНОВНЫЕ СТОП-КРИТЕРИИ (спрашиваем сразу, чтобы не терять время):
{{STOP_CRITERIA}} — список из 4-6 пунктов по нашим требованиям. 
Например: возраст, наличие мед. книжки, готовность к графику, прописка/регистрация, наличие опыта X, отсутствие судимости по статьям...

На любом "нет" — вежливо завершаем. НЕ скрипт-навязывание.

[1:30-2:30] БЫСТРЫЕ УТОЧНЕНИЯ ОПЫТА
— 2-3 вопроса в формате "да/нет" или 1 словом
— Что делал на предыдущей работе (30 секунд своими словами)

[2:30-3:30] УСЛОВИЯ (мы рассказываем, кандидат задаёт вопросы)
— ЗП вилка (точно, не "от", а диапазон)
— График
— Где находится объект, как добираться
— 1 "крючок" — то что отличает нас от других (обед, развозка, премия и т.п.)

[3:30-4:00] ЗАКРЫТИЕ
— "Подходит ли вам X [дата] в Y [время] для очного знакомства?"
— Подтверждение канала связи (WhatsApp?) для отправки деталей

ТРЕБОВАНИЯ:
— Каждый блок с репликой рекрутера + варианты ответов кандидата + ветвления
— 3 варианта обработки возражений: "подумаю", "ЗП мало", "далеко ехать"
— В конце: чек-лист "что записать в CRM"`,
